package dev.redstoneengineering.block;
import com.mojang.serialization.MapCodec;import dev.redstoneengineering.RedstoneEngineering;import dev.redstoneengineering.physics.InformationRuntime;import dev.redstoneengineering.physics.SerialNetwork;import net.minecraft.core.BlockPos;import net.minecraft.network.chat.Component;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;
/** Simplified serial link stores framed byte payload + symbol period at runtime. */
public class SerialDataLineBlock extends Block{public SerialDataLineBlock(Properties p){super(p);}@Override public MapCodec<SerialDataLineBlock> codec(){return RedstoneEngineering.SERIAL_DATA_LINE_CODEC.value();}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide)pl.displayClientMessage(Component.literal("Serial: byte="+InformationRuntime.value(l,"serial",p)+" period="+Math.max(1,InformationRuntime.aux(l,"serial",p))+"t valid="+InformationRuntime.valid(l,"serial",p)+" | "+SerialNetwork.diagnostics(l,p)),true);return InteractionResult.sidedSuccess(l.isClientSide);}}
